#pragma once

// GGML_CUDA_DEV_QUANTS (dev-only, default OFF): build CUDA quant kernels only for GGML_CUDA_DEV_QUANTS_TYPES
// (MMQ/MMVQ) and FA vec kernels only for GGML_CUDA_DEV_QUANTS_KV_TYPES. Dispatch cases for other types are
// compiled out (GGML_CUDA_DEVQ_ON / GGML_CUDA_DEVQ_KV_ON) and abort naming the type. OFF: every macro is a no-op.

#include "ggml.h"

#include <cstdlib>

#ifdef GGML_CUDA_DEV_QUANTS

// Generated by CMake: GGML_CUDA_DEVQ_<T> / GGML_CUDA_DEVQ_KV_<T> = 1 for kept types, plus
// GGML_CUDA_DEVQ_TYPES(X) / GGML_CUDA_DEVQ_KV_TYPES(X) lists.
#include "ggml-cuda-devquants-gen.h"

// Undefined identifiers evaluate to 0 in #if, so this is 1 for kept types and 0 otherwise.
#define GGML_CUDA_DEVQ_ON(T)    (GGML_CUDA_DEVQ_##T + 0)
#define GGML_CUDA_DEVQ_KV_ON(T) (GGML_CUDA_DEVQ_KV_##T + 0)

static inline bool ggml_cuda_devq_enabled(ggml_type type) {
#define GGML_CUDA_DEVQ_X(T) if (type == GGML_TYPE_##T) return true;
    GGML_CUDA_DEVQ_TYPES(GGML_CUDA_DEVQ_X)
#undef GGML_CUDA_DEVQ_X
    return false;
}

static inline bool ggml_cuda_devq_kv_enabled(ggml_type type) {
#define GGML_CUDA_DEVQ_X(T) if (type == GGML_TYPE_##T) return true;
    GGML_CUDA_DEVQ_KV_TYPES(GGML_CUDA_DEVQ_X)
#undef GGML_CUDA_DEVQ_X
    return false;
}

static inline void ggml_cuda_devq_check_type(ggml_type type) {
    if (!ggml_cuda_devq_enabled(type)) {
        GGML_ABORT("CUDA: quant type %s is not compiled in this dev build (GGML_CUDA_DEV_QUANTS=ON). "
                   "Add it to GGML_CUDA_DEV_QUANTS_TYPES or reconfigure with -DGGML_CUDA_DEV_QUANTS=OFF",
                   ggml_type_name(type));
    }
}

static inline void ggml_cuda_devq_check_kv_type(ggml_type type) {
    if (ggml_is_quantized(type) && !ggml_cuda_devq_kv_enabled(type)) {
        GGML_ABORT("CUDA: FlashAttention KV type %s is not compiled in this dev build (GGML_CUDA_DEV_QUANTS=ON). "
                   "Add it to GGML_CUDA_DEV_QUANTS_KV_TYPES or reconfigure with -DGGML_CUDA_DEV_QUANTS=OFF",
                   ggml_type_name(type));
    }
}

// Returns the first compiled-out type an op needs, or GGML_TYPE_COUNT if the op is fine.
static inline ggml_type ggml_cuda_devq_missing_type(const ggml_tensor * dst, bool * is_kv) {
    *is_kv = false;
    switch (dst->op) {
        case GGML_OP_MUL_MAT:
        case GGML_OP_MUL_MAT_ID:
        case GGML_OP_MOE_FUSED_UP_GATE:
        case GGML_OP_FUSED_UP_GATE:
            for (int j = 0; j < 2; ++j) {
                if (dst->src[j] && ggml_is_quantized(dst->src[j]->type) && !ggml_cuda_devq_enabled(dst->src[j]->type)) {
                    return dst->src[j]->type;
                }
            }
            break;
        case GGML_OP_FLASH_ATTN_EXT:
            for (int j = 1; j < 3; ++j) {
                if (ggml_is_quantized(dst->src[j]->type) && !ggml_cuda_devq_kv_enabled(dst->src[j]->type)) {
                    *is_kv = true;
                    return dst->src[j]->type;
                }
            }
            break;
        default:
            break;
    }
    return GGML_TYPE_COUNT;
}

// Early, op-level check so an excluded type fails on the first graph that uses it instead of
// silently taking a different (dequantize + cuBLAS) path.
static inline void ggml_cuda_devq_check_node(const ggml_tensor * dst) {
    bool is_kv;
    const ggml_type t = ggml_cuda_devq_missing_type(dst, &is_kv);
    if (t != GGML_TYPE_COUNT) {
        if (is_kv) ggml_cuda_devq_check_kv_type(t);
        else       ggml_cuda_devq_check_type(t);
    }
}

// Test-harness escape hatch: with GGML_CUDA_DEVQ_SKIP=1, supports_op reports ops that need a
// compiled-out type as unsupported (so test-backend-ops skips them) instead of aborting later.
static inline bool ggml_cuda_devq_skip_op(const ggml_tensor * op) {
    static const bool skip = [] { const char * e = getenv("GGML_CUDA_DEVQ_SKIP"); return e && atoi(e) != 0; }();
    bool is_kv;
    return skip && ggml_cuda_devq_missing_type(op, &is_kv) != GGML_TYPE_COUNT;
}

#else

#define GGML_CUDA_DEVQ_ON(T)    1
#define GGML_CUDA_DEVQ_KV_ON(T) 1

static inline void ggml_cuda_devq_check_type(ggml_type) {}
static inline void ggml_cuda_devq_check_kv_type(ggml_type) {}
static inline void ggml_cuda_devq_check_node(const ggml_tensor *) {}
static inline bool ggml_cuda_devq_skip_op(const ggml_tensor *) { return false; }

#endif // GGML_CUDA_DEV_QUANTS
